SELECT cequdet.STATUS dataStatus, /*1、数据状态*/ cequdet.REGIST_BANK_CODE registBankCode,/*2、发行机构代码*/ cequdet.INDENTIFY_MARK indentifyMark,/*3、识别标识*/ cequdet.REG_CODE regCode,/*4、产品登记编码*/ cequdet.BUSI_TYPE busiType,/*5、业务种类*/ cequdet.EQUITY_CONF_DATE eQuityConfDate,/*6、业务确认日期*/ cequdet.SHARE_CONF_DATETIME shareConfDatetime,/*7、业务确认时间*/ cequdet.CCY ccy,/*8、币种*/ cequdet.AMOUNT amount,/*9、金额*/ cequdet.AMOUNT_CNY amountCny,/*10、折算人民币金额*/ cequdet.PROD_VALUE prodValue,/*11、确认净值*/ cequdet.SHARES shares,/*12、份额*/ cequdet.FEE_AMT feeAmt,/*13、费用*/ cequdet.CHANNEL channel,/*14、渠道*/ cequdet.CONTRACT_NO contractNo,/*15、销售合同号*/ cequdet.BUSI_SEQNO busiSeqno,/*16、核心交易流水号*/ cequdet.FIN_ACC finAcc,/*17、理财账号*/ cequdet.CUST_CONTRACT_NO custContractNo,/*18、客户统一编号*/ cequdet.CUST_NAME custName,/*19、客户姓名*/ cequdet.FUND_ACC fundAcc,/*20、关联活期存款账号*/ cequdet.FUND_ACC_PLACE fundAccPlace,/*21、关联账号开户所在地*/ cequdet.IS_CONSIGN isConsign,/*22、是否代销*/ cequdet.AGENCY_CODE agencyCode,/*23、代销机构代码*/ cequdet.AGENCY_NAME agencyName,/*24、代销机构名称*/ cequdet.AGENCY_FSA agencyFsa,/*25、代销机构所属监管机构*/ cequdet.BUSI_FSA busiFsa,/*26、业务发生地所属监管*/ cequdet.TRAN_TELL_NAME tranTellName,/*27、交易柜员号*/ cequdet.REMARK remark/*28、备注*/ ,cequdet.INTERF_CHECK_RESULT interfCheckResult /*29、导入检查结果*/ ,cequdet.ACCOUNT account /*产品代码*/ FROM CHB_EQUDET cequdet where 1=1
#{regCode,jdbcType=VARCHAR}
#{account,jdbcType=VARCHAR}
AND cequdet.INDENTIFY_MARK LIKE concat(concat('%',#{indentifyMark}),'%')
#{busiType,jdbcType=VARCHAR}
AND DATE_FORMAT(cequdet.EQUITY_CONF_DATE,'%Y-%m-%d') >= STR_TO_DATE( #{equityConfDateStart},'%Y-%m-%d')
AND DATE_FORMAT(cequdet.EQUITY_CONF_DATE,'%Y-%m-%d') <= STR_TO_DATE( #{equityConfDateEnd},'%Y-%m-%d')
#{channel,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
and cequdet.BUSI_SEQNO = #{busiSeqno,jdbcType=VARCHAR}
(cequdet.BUSI_SEQNO=#{item.busiSeqnoKey} and cequdet.REG_CODE=#{item.regCodeKey} and cequdet.REGIST_BANK_CODE=#{item.registBankCodeKey})
ORDER BY cequdet.REG_CODE ASC, cequdet.EQUITY_CONF_DATE DESC, cequdet.SHARE_CONF_DATETIME DESC

    	select INDENTIFY_MARK indentifyMark,MERGER_INDENTIFY_MARK mergerindentifymark
    	from chb_equ_hold_check
		where INDENTIFY_MARK!=MERGER_INDENTIFY_MARK
			and status = 'E'
			and INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
			and REGIST_BANK_CODE = #{registBankCode,jdbcType=VARCHAR}

SELECT
A.REG_CODE regCode
FROM CHB_PRDRESIST_CODE A

    A.PRODID = #{account}
    and A.REG_CODE is not null


        AND (A.ORG_CODE IN


                null) OR A.ORG_CODE in (

            #{orgCode}
        )

SELECT DISTINCT A.PRODID id, A.PRODNAME text FROM CHB_PRDRESIST_CODE A
A.PRODNAME like #{likeStr}
order by A.PRODID

select count(*) from CHB_EQUDET
where REGIST_BANK_CODE=#{registBankCode}
and INDENTIFY_MARK=#{indentifyMark}
and BUSI_SEQNO = #{busiSeqno}

SELECT ce.STATUS dataStatus, /*1、数据状态*/ ce.REGIST_BANK_CODE registBankCode,/*2、发行机构代码*/ ce.INDENTIFY_MARK indentifyMark,/*3、识别标识*/ ce.REG_CODE regCode,/*4、产品登记编码*/ ce.BUSI_TYPE busiType,/*5、业务种类*/ ce.EQUITY_CONF_DATE eQuityConfDate,/*6、业务确认日期*/ ce.SHARE_CONF_DATETIME shareConfDatetime,/*7、业务确认时间*/ ce.CCY ccy,/*8、币种*/ ce.AMOUNT amount,/*9、金额*/ ce.AMOUNT_CNY amountCny,/*10、折算人民币金额*/ ce.PROD_VALUE prodValue,/*11、确认净值*/ ce.SHARES shares,/*12、份额*/ ce.FEE_AMT feeAmt,/*13、费用*/ ce.CHANNEL channel,/*14、渠道*/ ce.CONTRACT_NO contractNo,/*15、销售合同号*/ ce.BUSI_SEQNO busiSeqno,/*16、核心交易流水号*/ ce.FIN_ACC finAcc,/*17、理财账号*/ ce.CUST_CONTRACT_NO custContractNo,/*18、客户统一编号*/ ce.CUST_NAME custName,/*19、客户姓名*/ ce.FUND_ACC fundAcc,/*20、关联活期存款账号*/ ce.FUND_ACC_PLACE fundAccPlace,/*21、关联账号开户所在地*/ ce.IS_CONSIGN isConsign,/*22、是否代销*/ ce.AGENCY_CODE agencyCode,/*23、代销机构代码*/ ce.AGENCY_NAME agencyName,/*24、代销机构名称*/ ce.AGENCY_FSA agencyFsa,/*25、代销机构所属监管机构*/ ce.BUSI_FSA busiFsa,/*26、业务发生地所属监管*/ ce.TRAN_TELL_NAME tranTellName,/*27、交易柜员号*/ ce.REMARK remark/*28、备注*/ ,ce.ACCOUNT account /*产品代码*/ ,'' as interfCheckResult ,'' as agent ,cess.SUBMIT_FEEDBACK_MSG repFailedInfo FROM CHB_EQUDET_SUB ce LEFT JOIN CHB_EQUDET_SUBMIT_STATUS cess ON cess.SEQNO = ce.SUMIT_SEQ
cess.SUBMIT_FEEDBACK_STATUS = #{FEEDBACKSTATUS,jdbcType=VARCHAR}
#{SUMIT_SEQ,jdbcType=VARCHAR}
AND 1=2

SELECT ce.STATUS dataStatus, /*1、数据状态*/ ce.REGIST_BANK_CODE registBankCode,/*2、发行机构代码*/ ce.INDENTIFY_MARK indentifyMark,/*3、识别标识*/ ce.REG_CODE regCode,/*4、产品登记编码*/ ce.BUSI_TYPE busiType,/*5、业务种类*/ ce.EQUITY_CONF_DATE eQuityConfDate,/*6、业务确认日期*/ ce.SHARE_CONF_DATETIME shareConfDatetime,/*7、业务确认时间*/ ce.CCY ccy,/*8、币种*/ ce.AMOUNT amount,/*9、金额*/ ce.AMOUNT_CNY amountCny,/*10、折算人民币金额*/ ce.PROD_VALUE prodValue,/*11、确认净值*/ ce.SHARES shares,/*12、份额*/ ce.FEE_AMT feeAmt,/*13、费用*/ ce.CHANNEL channel,/*14、渠道*/ ce.CONTRACT_NO contractNo,/*15、销售合同号*/ ce.BUSI_SEQNO busiSeqno,/*16、核心交易流水号*/ ce.FIN_ACC finAcc,/*17、理财账号*/ ce.CUST_CONTRACT_NO custContractNo,/*18、客户统一编号*/ ce.CUST_NAME custName,/*19、客户姓名*/ ce.FUND_ACC fundAcc,/*20、关联活期存款账号*/ ce.FUND_ACC_PLACE fundAccPlace,/*21、关联账号开户所在地*/ ce.IS_CONSIGN isConsign,/*22、是否代销*/ ce.AGENCY_CODE agencyCode,/*23、代销机构代码*/ ce.AGENCY_NAME agencyName,/*24、代销机构名称*/ ce.AGENCY_FSA agencyFsa,/*25、代销机构所属监管机构*/ ce.BUSI_FSA busiFsa,/*26、业务发生地所属监管*/ ce.TRAN_TELL_NAME tranTellName,/*27、交易柜员号*/ ce.REMARK remark/*28、备注*/ ,ce.ACCOUNT account /*产品代码*/ ,'' as interfCheckResult ,'' as agent ,cess.SUBMIT_FEEDBACK_MSG repFailedInfo FROM CHB_EQUDET_SUB ce LEFT JOIN CHB_EQUDET_SUBMIT_STATUS cess ON cess.SEQNO = ce.SUMIT_SEQ
cess.SUBMIT_FEEDBACK_STATUS = #{FEEDBACKSTATUS,jdbcType=VARCHAR}
AND cess.REPORT_NO = #{reportNo,jdbcType=VARCHAR}
